class Solution {
public:
    long long minimumCost(int cost1, int cost2, int costBoth, int need1, int need2) {
        long long ans = LLONG_MAX;
        for (int x : {0, min(need1, need2), max(need1, need2)}) {
            long long cost = 1LL * x * costBoth
                + 1LL * max(0, need1 - x) * cost1
                + 1LL * max(0, need2 - x) * cost2;
            ans = min(ans, cost);
        }
        return ans;
    }
};
